-- ==========================================================================
-- RUMBEA - Entrega 3 - Script DML (1080 inserts)
-- Requiere: DDL/rumbea_ddl.sql. Ejecutar ANTES de PL-SQL/rumbea_plsql.sql.
--
-- Datos ficticios. Correos y enlaces usan example.com, reservado para ejemplos.
-- Fechas fijas para que los resultados sean iguales en cada ejecucion.
--
-- Casos que alimentan los reportes:
--   R1 administrador ADM01 (sede SED01): 14 dias de accesos y 15 resenas
--   R2 dueno OWN01: 12 establecimientos, 16 sedes y 14 eventos
--   R3 filtro Discoteca + Reggaeton y preferencias del cliente CLI001
-- ==========================================================================
SET DEFINE OFF
WHENEVER SQLERROR EXIT FAILURE ROLLBACK
SET FEEDBACK OFF

-- ==========================================================================
-- 1. Generos musicales: 12 filas
-- ==========================================================================

-- ==========================================================================
-- 2. Usuarios: 59 filas
-- 5 duenos, 14 administradores y 40 clientes. Algunos sin telefono (es opcional).
-- ==========================================================================

-- ==========================================================================
-- 3. Clientes: 40 filas
-- role toma su DEFAULT CLIENT.
-- ==========================================================================

-- ==========================================================================
-- 4. Duenos: 5 filas
-- role toma su DEFAULT OWNER.
-- ==========================================================================

-- ==========================================================================
-- 5. Establecimientos: 20 filas
-- OWN01 tiene 12 para que su reporte supere los 10 registros.
-- ==========================================================================

-- ==========================================================================
-- 6. Sedes: 28 filas
-- ==========================================================================

-- ==========================================================================
-- 7. Administradores: 14 filas
-- ADM14 esta inactivo para probar el trigger. SED15 en adelante no tiene admin.
-- ==========================================================================

-- ==========================================================================
-- 8. Tipo de cada sede: 28 filas
-- ==========================================================================

-- ==========================================================================
-- 9. Horarios: 84 filas
-- ==========================================================================

-- ==========================================================================
-- 10. Enlaces de interes: 20 filas
-- ==========================================================================

-- ==========================================================================
-- 11. Generos por sede: 56 filas
-- ==========================================================================

-- ==========================================================================
-- 12. Preferencias de clientes: 81 filas
-- ==========================================================================

-- ==========================================================================
-- 13. Eventos: 20 filas
-- OWN01 tiene 14 eventos para el Reporte 2.
-- ==========================================================================

-- ==========================================================================
-- 14. Sedes de cada evento: 28 filas
-- ==========================================================================

-- ==========================================================================
-- 15. Accesos a perfiles: 278 filas
-- SED01 recibe accesos en 14 dias distintos (Reporte 1).
-- visitTimeIn usa HH24MI como entero: 2130 es 21:30.
-- ==========================================================================

-- ==========================================================================
-- 16. Favoritos: 207 filas
-- SED16 y SED28 no tienen favoritos, para evidenciar los OUTER JOIN.
-- ==========================================================================

-- ==========================================================================
-- 17. Resenas: 84 filas
-- Toda resena es posterior a una visita. CLI002 resena SED01 dos veces.
-- ==========================================================================

-- ==========================================================================
-- 18. Historial de actualizaciones: 16 filas
-- Es historia: se carga antes de crear el trigger y coincide con el estado actual de cada sede.
-- ==========================================================================

COMMIT;
SET FEEDBACK ON
PROMPT DML de Rumbea cargado.
